import { Group, PlaneGeometry, MeshBasicNodeMaterial, Mesh, Color } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // --- Brushed metal plane ---
  const geometry = new PlaneGeometry(1, 1); // size will be set later based on aspect or explicit? Use default 1x1, adapter may scale.
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    map: null,
    needsUpdate: false,
  });
  const plane = new Mesh(geometry, material);
  group.add(plane);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Text content ---
  // We only create text for the given item (role 'headline')
  const textItem = items.find((item) => item.role === 'headline');
  if (textItem) {
    const fontSize = textItem.typography?.fontSize ?? 39;
    const color = textItem.color ?? config.colors?.paper ?? '#e8ecf2';
    const textMesh = ctx.fontAtlas.createText(textItem.text, {
      fontSize,
      color,
      align: 'center',
    });
    // Position text slightly in front of the plane
    textMesh.position.z = 0.01;
    textMesh.scale.set(0.001, 0.001, 0.001); // Adjust scale if needed; typically fontAtlas returns scaled appropriately
    // Or we can leave scale as is; assume createText works in scene units already.
    // To centre on the plane, we can compute offset if needed. For simplicity, just add.
    group.add(textMesh);
  }

  // --- Handlers (no interactions) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // Kill any GSAP timelines (none)
  };

  return group;
}
